declare(strict_types=1);define('G5_PATH','/tmp/noa-creator-site');require __DIR__.'/../../bridge/creator-enrollment-core.php';require __DIR__.'/../../bridge/channel-view.php';
function must($ok,$why){if(!$ok)throw new RuntimeException($why);}
$im=imagecreatetruecolor(20,20);imagealphablending($im,false);imagesavealpha($im,true);imagefill($im,0,0,imagecolorallocatealpha($im,0,0,0,127));imagesetpixel($im,10,10,imagecolorallocatealpha($im,225,179,98,0));imagesetpixel($im,5,5,imagecolorallocatealpha($im,225,179,98,64));
foreach(['png','webp'] as $format){ob_start();$format==='png'?imagepng($im):imagewebp($im,null,100);$original=ob_get_clean();$converted=nce_symbol_png($original);$decoded=imagecreatefromstring($converted);must(imagecolorsforindex($decoded,imagecolorat($decoded,0,0))['alpha']===127,'transparent corner preserved '.$format);must(imagecolorsforindex($decoded,imagecolorat($decoded,10,10))['alpha']===0,'opaque pixel preserved');must(abs(imagecolorsforindex($decoded,imagecolorat($decoded,5,5))['alpha']-64)<=1,'semi-transparent pixel preserved');imagedestroy($decoded);if($format==='png')file_put_contents('/tmp/noa-channel-alpha.png',$original);}
ob_start();imagejpeg($im);$jpg=ob_get_clean();$decoded=imagecreatefromstring(nce_symbol_png($jpg));must(imagecolorsforindex($decoded,imagecolorat($decoded,0,0))['alpha']===0,'JPEG stays opaque');imagedestroy($decoded);imagedestroy($im);
