must(nc_channel(['title'=>'채널','profileBackgroundOpacity'=>0])['profileBackgroundOpacity']===0,'zero allowed');must(!isset(nc_channel(['title'=>'채널'])['profileBackgroundOpacity']),'old clients do not reset settings');
