$out=ncv_project($rows,['public'=>['public-alias']],hash('sha256','owner'),fn($key)=>$key==='pending'?null:['audio'=>'','cover'=>'/default.png']);must(array_column($out,'key')===['public','list','private-members'],'owner/public/ready/trash projection');must($out[1]['members']===[['key'=>'public-alias']],'public member aliases only');must($out[2]['act']===0,'private members cannot become implicit ACT');$encoded=json_encode($out);must(!str_contains($encoded,'secret')&&!str_contains($encoded,'foreign')&&!str_contains($encoded,'ownerId'),'private fields absent');
